    newMenuLink := BarManager.PopupMenuLinks.Add;
    newMenuLink.Control := TWinControl(AControl);
    if FIsDesignMode then
      newMenuLink.PopupMenu := pmDesign
    else
      newMenuLink.PopupMenu := pmForm;
