    dxBarButtonStartDesign.Visible := ivNever;
    {if dxBarButtonUchovavatHodnotyVDesignModu.Down then
      FWorkData:=GetValuesData;}
  end
  else begin
    dxBarButtonStartDesign.Visible := ivAlways;
    BarManager.Bars[0].Visible:=TRUE;
    BarManager.Bars[1].Visible:=TRUE;
    BarManager.Bars[2].Visible:=TRUE;
  end;
  if not AActive and (mtContentPage.Value < cTopUserContentKey) then begin
    FIsLoadingContent := TRUE;
