  if ACalcDisable then begin
    mxStatusBar1.Panels[2].ImageIndex := 3;
    mxStatusBar1.Panels[2].Hint := sSbHintCalcDisabled;
  end
  else begin
    mxStatusBar1.Panels[2].ImageIndex := 2;
    mxStatusBar1.Panels[2].Hint := sSbHintCalcEnabled;
  end;
  if mtTskp.Active and (mtTskp.RecordCount > 0) then
    SetFormUserSetting(cUSCalcDisabled, BoolToStr(ACalcDisable, TRUE));
end; {SetDisableClacFlag}

function TfaMain.GetFormUserSetting(const ASetting: string): string;
var
  sl: TStringList;
begin
  sl := TStringList.Create;
  try
    if mtTskp.Active and (mtTskp.RecordCount > 0) then begin
      sl.Text := mtTskpUserSettings.Value;
      Result := sl.Values[ASetting];
    end
    else
      Result := '';
  finally
    sl.Free;
  end;
end; {GetFormUserSetting}

procedure TfaMain.SetFormUserSetting(const ASetting, AValue: string);
var
  sl: TStringList;
begin
  sl := TStringList.Create;
  try
    if mtTskp.Active and (mtTskp.RecordCount > 0) then begin
      sl.Text := mtTskpUserSettings.Value;
      sl.Values[ASetting] := AValue;
      mtTskp.Edit;
      mtTskpUserSettings.Value := sl.Text;
      mtTskp.Post;
    end;
  finally
    sl.Free;
  end;
end; {SetFormUserSetting}

{-----------------------------------------------------------------------------
 SetLockFlag
   Nastavi priznak zamceneho formulare
 Vstup: ALocked ... zda je formular zamceny
 -----------------------------------------------------------------------------}

procedure TfaMain.SetLockFlag(ALock: boolean);
var
  ro: boolean;
begin
  if ALock <> FStateFormLocked then begin
    FStateFormLocked := ALock;
    ro := mtValues.ReadOnly;
    mtValues.ReadOnly := FALSE; // kvuli spravnemu nastaveni changeflagu
    try
      SetChangeFlag(TRUE);
    finally
      mtValues.ReadOnly := ro;
    end;
    SetReadOnly(ALock);
  end;
  if FStateFormLocked then begin
    mxStatusBar1.Panels[3].ImageIndex := cIndexLockPicture;
    if FStateFormReadOnlyLAN then
      mxStatusBar1.Panels[3].Hint := sSbHintReadOnly
    else
      mxStatusBar1.Panels[3].Hint := sSbFormLocked;
  end
  else begin
    mxStatusBar1.Panels[3].ImageIndex := -1;
    mxStatusBar1.Panels[3].Hint := '';
    ShowHintSb('');
  end;
end; {SetLockFlag}

function TfaMain.GetLockFlag: boolean;
begin
  Result := FStateFormLocked;
end; {GetLockFlag}

function TfaMain.LoadContent(const AFileName: string): boolean;
begin
  StartWait;
  FLastContentKey := -1;
  FIsLoadingContent := TRUE;
  mtContent.DisableControls;
  try
    mtContent.DefaultFormat := mtSaveFormat;
    Result := LoadMtFromZip(mtContent, FDefFileName, dpsw);
    if Result then
      SetMaxContentKey;
    UpdateTreeViewContent;
    mtContent.First;
  finally
    mtContent.EnableControls;
    FIsLoadingContent := FALSE;
    StopWait;
  end;
end; {LoadContent}

function TfaMain.LoadFields(const AFileName: string): boolean;
begin
  StartWait;
  try
    mtFields.DisableControls; //ma zustat trvale vypnute
    DisconnectMtValues;
    mtFields.DefaultFormat := mtPrgTablesFormat;
    Result := LoadMtFromZip(mtFields, FDefFileName, dpsw);
  finally
    StopWait;
  end;
end; {LoadFields}

function TfaMain.LoadFieldsInfo(const AFileName: string): boolean;
begin
  mtFieldsInfo.DefaultFormat := mtPrgTablesFormat;
  Result := LoadMtFromZip(mtFieldsInfo, FDefFileName, dpsw);
end; {LoadFieldsInfo}

function TfaMain.LoadMtValues(const AFileName: string): boolean;
var
  ro: boolean;
  text: string;
begin
  StartWait;
  mtValues.DisableControls;
  ro := mtValues.ReadOnly;
  mtValues.ReadOnly := FALSE;
  try
    Result := LoadTextFromZip(FDefFileName, mtValues.Name, text, dpsw);
    if Result then
    try
      Result := RestoreMtValuesDef(text);
    except
      on E: Exception do begin
        ShowMessage(Format(sMsgErrLoadmtValues, [E.Message]));
        Result := FALSE;
      end;
    end;
  finally
    mtValues.ReadOnly := ro;
    mtValues.EnableControls;
    StopWait;
  end;
end; {LoadMtValues}

function TfaMain.LoadControlsNamesList(const AFileName: string): boolean;
var
  text: string;
begin
  StartWait;
  try
    Result := LoadTextFromZip(FDefFileName, cControlsNamesListFN, text, dpsw);
    if Result then
      FControlsNamesList.Text := text
    else
      FControlsNamesList.Clear;
  finally
    StopWait;
  end;
end; {LoadControlsNamesList}

//nastavi pro vypoctene udaje read only controls a vzhled

procedure TfaMain.SetCalcEdits(AReset: boolean; ASetBorderInfo: boolean =
  FALSE);
const
  cBorderInfoColor = clMaroon;
var
  i: integer;
  c: TControl;
begin
  if not FIsDesignMode and mtFields.Active then begin
    for i := 0 to sbForm.ControlCount - 1 do begin
      c := sbForm.Controls[i];
      if (c is TfaEdit) or (c is TcxDBCheckBox) or
        (c is TcxDBMemo) then begin
        if mtFields.FindKey([UpperCase(c.Name)])
          {mtFields.Locate(mtFieldsName.FieldName, c.Name, //opt
          [loCaseInsensitive])}then begin
          if mtFieldsHasCalc.Value then begin
            if AReset then
              SetCalcControl(c, AReset)
            else
              SetCalcControl(c, not (mtFieldsIsCalculated.Value and
                not mtFieldsCalcWithoutShowing.Value));
          end;
          if ASetBorderInfo and (c is TfaEdit) then begin
            TfaEdit(c).HighlightList := mtFieldsHasList.Value;
            TfaEdit(c).HighlightDefVal := mtFieldsHasDefault.Value;
            TfaEdit(c).HighlightListColor := DarkColor(clHighLight,20){cBorderInfoColor};
            TfaEdit(c).HighlightDefValColor := DarkColor(clHighLight,20);
          end
          else if ASetBorderInfo and (c is TCxDBMemoEx) then begin
            TCxDBMemoEx(c).HighlightList := mtFieldsHasList.Value;
            TCxDBMemoEx(c).HighlightDefVal := mtFieldsHasDefault.Value;
            TCxDBMemoEx(c).HighlightListColor := DarkColor(clHighLight,20){cBorderInfoColor};
            TCxDBMemoEx(c).HighlightDefValColor := DarkColor(clHighLight,20);
          end;
        end;
      end;
    end;
    DoEnable;//opt - tady to asi musime nechat
  end;
end; {SetCalcEdits}

//nastavi pro checkboxy obsluhu OnClick

procedure TfaMain.SetCbOnClick;
var
  i: integer;
  c: TControl;
begin
  for i := 0 to sbForm.ControlCount - 1 do begin
    c := sbForm.Controls[i];
    if c is TcxDBCheckBox then begin
      TcxDBCheckBox(c).OnClick := CheckBoxClick;
      LinkFldPopupMenu(c);
    end
    else if c is TcxDBMemo then begin
      LinkFldPopupMenu(c);
      TcxDBMemo(c).OnEnter := DoOnMemoEnter;
      TcxDBMemo(c).OnPostEditValue := DoOnMemoExit;
    end
    else if c is TButton then begin
      if not FIsDesignMode then
        TButton(c).OnClick := ButtonClick;
    end
    else if c is TpsvWebLabel then begin
      if not FIsDesignMode then
        TpsvWebLabel(c).OnClick := WebLabelClick;
    end
    else if c is THTMLStaticText then begin
      if not FIsDesignMode then begin
        THTMLStaticText(c).OnClick := HTMLStaticTextClick;
        THTMLStaticText(c).OnAnchorClick := HTMLStaticTextAnchorClick;
      end;
    end;
  end;
end; {SetCbOnClick}

//zobrazi nasledujici stranu

procedure TfaMain.ShowNextPage;
var
  l1,l2,l3,l4, oldPos: integer;
begin
{$IFDEF PROFILER}TimeLog('+++ Start ShowNextPage'); {$ENDIF PROFILER}
  StartWait;
  try
    // Pokud je na pozadi obrazek a nejsme na konci tak jen scrolujeme
    if (mtContentImageHeight.Value>0) or (IsPaintBoxReadyForUse) then
    begin
      with sbForm.VertScrollBar do
      begin
        oldPos:=Position;
        Position := Position + sbForm.Height;
        if Position<>oldPos then
        EXIT;
      end;
    end;

    // Na dalsi stranku
    {TryPostMtValues;}
    if not mtContent.EOF then begin begin
        FIsLoadingContent := TRUE;
        try
          SetFocusContent;
        finally
          FIsLoadingContent := FALSE;
        end;
      end;
      HideEdit;
{$IFDEF PROFILER}TimeLog('HE'); {$ENDIF PROFILER}
      l1 := mtContentPage.Value;
      l2 := mtContentSection.Value;
      l3 := mtContentLevel3.Value;
      l4 := mtContentLevel4.Value;
      mtContent.Next;
      while not mtContent.EOF and
        (l1=mtContentPage.Value) and
        (l2=mtContentSection.Value) and
        (l3=mtContentLevel3.Value) and
        (l4=mtContentLevel4.Value)
        {not FieldIsEmpty(mtContentDefaultControlName)} do
        mtContent.Next;
      LocateTreeItem;
      if TRUE {not FParamFastScroll} then begin
        if mtContentDefaultControlName.Value='' then
          FocusFirstControl
        else
          TryFocusControlByName(mtContentDefaultControlName.Value);
      end;
      ApplyFormCaption;
    end;
  finally
    StopWait;
  end;
{$IFDEF PROFILER}TimeLog('+++ End ShowNextPage'); {$ENDIF PROFILER}
end; {ShowNextPage}

//zobrazi predchozi stranu

procedure TfaMain.ShowPriorPage;
var
  oldPos: integer;

  function HasPreviousRecordSameKeys: boolean;
  var
    l1,l2,l3,l4,k: integer;
  begin
    l1 := mtContentPage.Value;
    l2 := mtContentSection.Value;
    l3 := mtContentLevel3.Value;
    l4 := mtContentLevel4.Value;
    k := mtContentKey.Value;
    mtContent.Prior;
    Result :=
      (l1=mtContentPage.Value) and
      (l2=mtContentSection.Value) and
      (l3=mtContentLevel3.Value) and
      (l4=mtContentLevel4.Value) and
      (k<>mtContentKey.Value);
    if k<>mtContentKey.Value then
      mtContent.Next;
  end;

begin
  StartWait;
  try
    // Pokud je na pozadi obrazek (nebo PDF) a nejsme na zacatku tak jen scrolujeme
    if ((mtContentImageHeight.Value>0) or (IsPaintBoxReadyForUse)) and
      ((not mtContent.BOF) or (sbForm.VertScrollBar.Position>0)) then
    begin
      with sbForm.VertScrollBar do
      begin
        oldPos:=Position;
        Position := Position - sbForm.Height;
        if Position<>oldPos then
        EXIT;
      end;
    end;

    // Na dalsi stranku
    {TryPostMtValues;}
    if not mtContent.BOF then begin
      SetFocusContent;
      HideEdit;
      mtContent.Prior;
      while HasPreviousRecordSameKeys do
        mtContent.Prior;
      LocateTreeItem;
      ApplyFormCaption;

      // Pokud je na pozadi obrazek a neni zobrazeny cely tak posuneme na posledni cast
      if (mtContentImageHeight.Value>0) then
      begin
        with sbForm.VertScrollBar do
        begin
          Position := Position + mtContentImageHeight.Value;
          EXIT;
        end;
      end;
      // ---
      // Pokud je na pozadi PDF a neni zobrazeny cely tak posuneme na posledni cast
      if (IsPaintBoxReadyForUse)  then
      begin
        with sbForm.VertScrollBar do
        begin
          Position := Position + PaintBox.Height;
          EXIT;
        end;
      end;
      // ---

      if TRUE {not FParamFastScroll} then begin
        if mtContentDefaultControlName.Value='' then
          FocusFirstControl
        else
          TryFocusControlByName(mtContentDefaultControlName.Value);
      end;
    end;

  finally
    StopWait;
  end;
end;{ShowPriorPage}

