//ulozi definici do souboru

procedure TfaMain.SaveDef;
var
  isDesignMode, mtValReadOnly: boolean;
begin
  if FDefReadOnly then
    MessageWarn(Caption,
      'Nelze uložit definici, soubor je pouze pro čtení. Můžete uložit definici volbou Uložit jako.',
      [MBOK])
  else begin
    isDesignMode := FIsDesignMode;
    mtValReadOnly := mtValues.ReadOnly;
    FIsDesignMode := TRUE;
      //aby pri ukladani definice mimo design modenebyl problem s nastavovanim check boxu
    try
      if Designer.Active then
        Designer.Active := FALSE;
      //ulozit do souboru
      if FDefFileName = '' then begin
        with SaveDialog1 do begin
          DefaultExt := cDefDefaultExt;
          Filter := cDefOpenSaveFilter;
          if Execute then begin
            if not FileExists(FileName) or
              (MessageAsk(Caption,Format(sMsgFileNotExistsAsk, [FileName]),
              [MBYES, MBNO]) = IDYES) then begin
              //ulozit do souboru
              SaveDataDef(FileName);
              //ulozit pouzite jmeno
              FDefFileName := FileName;
              //nastavit tlacitko
              SetChangeFlag(FALSE);
            end;
          end;
        end;
      end
      else begin
        SaveDataDef(FDefFileName);
        SetChangeFlag(FALSE);
      end;
      //
      ApplyMainCaption(FDefFileName);
    finally
      FIsDesignMode := isDesignMode;
      mtValues.ReadOnly := mtValReadOnly;
    end;
  end;
end; {SaveDef}

//ulozi definici do jineho souboru

procedure TfaMain.SaveAsDef;
begin
  if Designer.Active then
    Designer.Active := FALSE;
  with SaveDialog1 do begin
    DefaultExt := cDefDefaultExt;
    Filter := cDefOpenSaveFilter;
    FileName := FDefFileName;
    if Execute then begin
      if not FileExists(FileName) or
        (MessageAsk(Caption,Format(sMsgFileNotExistsAsk, [FileName]),
        [MBYES, MBNO]) = IDYES) then begin
        //ulozit do souboru
        SaveDataDef(FileName);
        //ulozit pouzite jmeno
        FDefFileName := FileName;
        //nastavit tlacitka
        SetChangeFlag(FALSE);
        SetLastFiles;
        FDefReadOnly := FALSE;
{$IFDEF STANDALONE}
        faSaveForm.Visible := TRUE;
{$ENDIF STANDALONE}
        ApplyMainCaption(FDefFileName);
      end;
    end;
  end;
end; {SaveAsDef}

procedure TfaMain.CloseDef;
var
  res: integer;
begin
  //pokud neni soubor ulozen, zeptat se na ulozeni a ulozit
  if FStateFormWasChanged then begin
    res := MessageAsk(Caption, sMsgAskSaveFile +  ' ' +
      FDefFileName + '?', [MBYES, MBNO, MBCANCEL]);
    if res = IDYES then
      SaveDef
    else if res = IDCANCEL then
      EXIT;
  end;
  mtContent.EmptyTable;
  LoadPage; //aby zmizely poznamky pokud byly aktivni
  SetDesignButtons;
  SetLastFiles;
  CloseData;
  FDefFileName := '';
  ApplyMainCaption(FDefFileName);
  ApplyFormCaption;
  SetChangeFlag(FALSE);
end; {CloseDef}

