//vraci Top u vsech komponent mimo CxDBCheckBox, kde vraci hodnotu nizsi
//  CxDBCheckBox ma standardne vysku 21 a nevejde se tak do radku s edity
//  pro posun kurzoru budeme brat v uvahu jen vysku ramecku boxu

function TfaMain.TopC(AControl: TControl): integer;
begin
  if AControl is TCxDBCheckBox then
    Result := AControl.Top + 7
  else
    Result := AControl.Top;
end; {TopC}

//vraci Height u vsech komponent mimo CxDBCheckBox, kde vraci hodnotu nizsi
//  CxDBCheckBox ma standardne vysku 21 a nevejde se tak do radku s edity
//  pro posun kurzoru budeme brat v uvahu jen vysku ramecku boxu

function TfaMain.HeightC(AControl: TControl): integer;
begin
  if AControl is TCxDBCheckBox then
    Result := AControl.Height - 8
  else
    Result := AControl.Height;
end; {HeightC}

//zjisti jestli je AControl editacni componenta, kterou podporujeme a je visible

function TfaMain.IsControlEditable(AC: TControl;
  ACanReadOnly: boolean = FALSE): boolean;
begin
  Result :=
    (AC is TfaEdit) and (TfaEdit(AC).Visible) and
    ((TfaEdit(AC).Tag = 0) or ACanReadOnly) or
    (AC is TcxDBCheckBox) and (TcxDBCheckBox(AC).Visible)
    and ((TcxDBCheckBox(AC).Tag = 0) or ACanReadOnly) or
    (AC is TcxDBMemo) and (TcxDBMemo(AC).Visible)
    and ((not TcxDBMemo(AC).Properties.ReadOnly) or ACanReadOnly) or
    (AC is TcxListBoxEx) and (TcxListBoxEx(AC).Visible) or
    (AC is TRichEdit) and (TRichEdit(AC).Visible);
end; {IsControlEditable}

function TfaMain.IsControlInRow(AC1, AC2: TControl): boolean;
begin
  Result := (AC1 = nil) or (AC2 = nil) or
    ((TopC(AC2) > TopC(AC1) - HeightC(AC2) + 3{1}) and
    (TopC(AC2) < TopC(AC1) + HeightC(AC1) - 3{1}));
end; {IsControlInRow}

function TfaMain.IsControlInCol(AC1, AC2: TControl): boolean;
begin
  Result := (AC1 = nil) or (AC2 = nil) or
    ((AC2.Left > AC1.Left - AC2.Width + 3{1}) and (
    AC2.Left < AC1.Left + AC1.Width - 3{1}));
end; {IsControlInRow}

//najde control ktery nejvice nahore vlevo pod urovni ATop vcetne
//  prvni vlevo nahore je control nejvice vlevo, prekryvajici se s nejvyssim

function TfaMain.GetFirstControl(ATop: integer = -maxint;
  ACanReadOnly: boolean = FALSE): TControl;
var
  i, xmin, ymin: integer;
  c, chigh, cleft: TControl;
begin
  if sbNotes.Visible then begin
    Result := reNotes;
    EXIT;
  end;
  xmin := maxint; //nejmensi Left
  ymin := maxint; //nejmensi Top
  chigh := nil; //nejvyssi control
  cleft := nil; //nejlevejsi control v rakdu s nejvyssim
  for i := 0 to sbForm.ControlCount - 1 do begin
    c := sbForm.Controls[i];
    //control ktery zacina nejvys
    if IsControlEditable(c, ACanReadOnly) and ((TopC(c)+3) >= (ATop{0})) and (TopC(c) <
      ymin) then begin
      xmin := c.Left;
      ymin := TopC(c);
      chigh := c;
    end;
  end;
  for i := 0 to sbForm.ControlCount - 1 do begin
    c := sbForm.Controls[i];
    //pokud je na stejnem radku jako nejvyssi jeste jiny control, tak bereme ten co je vlevo
    if IsControlEditable(c, ACanReadOnly) and ((TopC(c)+3) >= (ATop{0})) and
      IsControlInRow(chigh, c) and (c.Left < xmin) then begin
      xmin := c.Left;
      cleft := c;
    end;
  end;
  if cleft <> nil then
    Result := TControl(cleft)
  else
    Result := TControl(chigh);
end; {GetFirstControl}

//najde control ktery nejvice vpravo dole nad urovni ADown vcetne
//  posledni vpravo dole je control nejvice vlpravo, prekryvajici se s nejnizsim

function TfaMain.GetLastControl(ATop: integer = maxint;
  ACanReadOnly: boolean = FALSE): TControl;
var
  i, xmax, ymax: integer;
  c, clow, cright: TControl;
begin
  xmax := -maxint; //nejvyssi Right
  ymax := -maxint; //nejvyssi Top
  clow := nil; //nejnizsi control
  cright := nil; //nejpravejsi control v radku s nejnizsim
  for i := 0 to sbForm.ControlCount - 1 do begin
    c := sbForm.Controls[i];
    //control ktery konci nejniz
    if IsControlEditable(c, ACanReadOnly) and ((TopC(c) + HeightC(c) - 3{2}) < ATop)
      and
      ((TopC(c) + HeightC(c)) > ymax) then begin
      xmax := c.Left;
      ymax := TopC(c) + HeightC(c);
      clow := c;
    end;
  end;
  for i := 0 to sbForm.ControlCount - 1 do begin
    c := sbForm.Controls[i];
    //pokud je na stejnem radku jako nejnizssi jeste jiny control,
    //  tak bereme ten co je vpravo
    if IsControlEditable(c, ACanReadOnly) and ((TopC(c) + HeightC(c) - 3{2}) < ATop)
      and
      IsControlInRow(clow, c) and (c.Left > xmax) then begin
      xmax := c.Left;
      cright := c;
    end;
  end;
  if cright <> nil then
    Result := TControl(cright)
  else
    Result := TControl(clow);
end; {GetLastControl}

//najde control ktery nejvice nahore vpravo od urovne ATop vcetne

function TfaMain.GetFirstRightControl(ALeft: integer = -maxint): TControl;
var
  i, xmin, ymin: integer;
  c, chigh, cleft: TControl;
begin
  if sbNotes.Visible then begin
    Result := reNotes;
    EXIT;
  end;
  xmin := maxint; //nejmensi Left
  ymin := maxint; //nejmensi Top
  chigh := nil; //nejvyssi control
  cleft := nil; //nejlevejsi control v rakdu s nejvyssim
  for i := 0 to sbForm.ControlCount - 1 do begin
    c := sbForm.Controls[i];
    //control ktery zacina nejvys
    if IsControlEditable(c) and (TopC(c) >= 0) and (TopC(c) < ymin) and
      (c.Left >= ALeft) then begin
      xmin := c.Left;
      ymin := TopC(c);
      chigh := c;
    end;
  end;
  for i := 0 to sbForm.ControlCount - 1 do begin
    c := sbForm.Controls[i];
    //pokud je na stejnem radku jako nejvyssi jeste jiny control, tak bereme ten co je vlevo
    if IsControlEditable(c) and (TopC(c) >= 0) and
      IsControlInRow(chigh, c) and (c.Left < xmin) and
      (c.Left >= ALeft) then begin
      xmin := c.Left;
      cleft := c;
    end;
  end;
  if cleft <> nil then
    Result := TControl(cleft)
  else
    Result := TControl(chigh);
end; {GetFirstRightControl}

//najde control, ktery je nejblize vpravo od AC
//  kdyz je to posledni control vpravo, tak vraci AC

function TfaMain.GetRightControl(AC: TControl): TControl;
var
  i, xmin: integer;
  c, cmin: TControl;
begin
  xmin := maxint;
  cmin := AC;
  for i := 0 to sbForm.ControlCount - 1 do begin
    c := sbForm.Controls[i];
    if IsControlEditable(c) and (c <> AC) and IsControlInRow(AC, c) and
      (c.Left > AC.Left) and (c.Left < xmin) then begin
      xmin := c.Left;
      cmin := c;
    end;
  end;
  Result := TControl(cmin);
end; {GetRightControl}

//najde control, ktery je nejblize vlevo od AC

function TfaMain.GetLeftControl(AC: TControl): TControl;
var
  i, xmin: integer;
  c, cmin: TControl;
begin
  xmin := -maxint;
  cmin := AC;
  for i := 0 to sbForm.ControlCount - 1 do begin
    c := sbForm.Controls[i];
    if IsControlEditable(c) and (c <> AC) and IsControlInRow(AC, c) and
      (c.Left < AC.Left) and (c.Left > xmin) then begin
      xmin := c.Left;
      cmin := c;
    end;
  end;
  Result := TControl(cmin);
end; {GetLeftControl}

//najde control, ktery je nejblize pod AC

function TfaMain.GetDownControl(AC: TControl): TControl;
var
  i, ymin: integer;
  c, cmin: TControl;
begin
  ymin := maxint;
  cmin := AC;
  for i := 0 to sbForm.ControlCount - 1 do begin
    c := sbForm.Controls[i];
    if IsControlEditable(c) and (c <> AC) and IsControlInCol(AC, c) and
      (TopC(c) > TopC(AC)) and (TopC(c) < ymin) then begin
      ymin := TopC(c);
      cmin := c;
    end;
  end;
  Result := TControl(cmin);
end; {GetDownControl}

//najde control, ktery je nejblize nad AC

function TfaMain.GetUpControl(AC: TControl): TControl;
var
  i, ymin: integer;
  c, cmin: TControl;
begin
  ymin := -maxint;
  cmin := AC;
  for i := 0 to sbForm.ControlCount - 1 do begin
    c := sbForm.Controls[i];
    if IsControlEditable(c) and (c <> AC) and IsControlInCol(AC, c) and
      (TopC(c) < TopC(AC)) and (TopC(c) > ymin) then begin
      ymin := TopC(c);
      cmin := c;
    end;
  end;
  Result := TControl(cmin);
end; {GetDownControl}

//najde dalsi control vpravo nebo nize

function TfaMain.GetNextControl(AC: TControl): TControl;
var
  c: TControl;
begin
  c := GetRightControl(AC);
  if c <> AC then
    Result := c
  else
    Result := GetFirstControl(TopC(AC) + HeightC(AC) - 1);
  if Result = nil then
    Result := AC;
end; {GetNextControl}

//najde predchozi control vlevo nebo vyse

function TfaMain.GetPreviousControl(AC: TControl): TControl;
var
  c: TControl;
begin
  c := GetLeftControl(AC);
  if c <> AC then
    Result := c
  else
    Result := GetLastControl(TopC(AC));
  if Result = nil then
    Result := AC;
end; {GetPreviousControl}

function TfaMain.GetControlByName(const AControlName: string): TControl;
var
  i: integer;
  c: TControl;
begin
  Result := nil;
  for i := 0 to sbForm.ControlCount - 1 do begin
    c := sbForm.Controls[i];
    if (AnsiUppercase(c.Name) = AnsiUppercase(AControlName)) and
      IsControlEditable(c) then begin
      Result := c;
      BREAK;
    end;
  end;
end; {GetControlByName}

function TfaMain.TryFocusControlByName(const AControlName: string): boolean;
var
  c: TControl;
begin
  c := GetControlByName(AControlName);
  if c <> nil then begin
    FActuallyControl := c;
    FocusActuallyControl;
    Result := TRUE;
  end
  else
    Result := FALSE;
end; {TryFocusControlByName}

//select udaje mysi

procedure TfaMain.DoOnMouseDown(Sender: TObject; Button: TMouseButton;
  Shift: TShiftState; X, Y: Integer);
begin
  if (Sender is TCxDBCheckBoxEx) or (Sender is TCxDBMemoEx) or
    (Sender is TButton) or (Sender is TcxListBoxEx) then
    HideEdit;
  if Sender is TControl then begin
    FActuallyControl := TControl(Sender);
    FocusActuallyControl;
  end;
end; {DoOnMouseDown}

procedure TfaMain.DoOnMouseMove(Sender: TObject;
  Shift: TShiftState; X, Y: Integer);
begin
  if PtInRect(TfaEdit(Sender).HighlightListRect, Point(X, Y)) then
    TfaEdit(Sender).Hint := sFldHasLookup
  else if PtInRect(TfaEdit(Sender).HighlightDefValRect, Point(X, Y)) then
    TfaEdit(Sender).Hint := sFldHasDefVal
  else
    TfaEdit(Sender).Hint := '';
end;

procedure TfaMain.DoOnMemoEnter(Sender: TObject);
begin
  if Sender is TcxDBMemo then begin
    if FHistEditHasWrite then begin
      FHistEditLastValue := TcxDBMemo(Sender).EditingText;
      FHistMemoLastValue := FHistEditLastValue;
    end;
    //
    FMemoValue := TcxDBMemo(Sender).Text;
    TcxDBMemo(Sender).SelectAll;
    FEditingState := FALSE;
  end;
end; {DoOnMemoEnter}

procedure TfaMain.DoOnMemoExit(Sender: TObject);
begin
  if Sender is TcxDBMemo then begin
    if TcxDBMemo(Sender).EditingText<>FHistMemoLastValue then
      SetHistEdit(TcxDBMemo(Sender).Name, TcxDBMemo(Sender).EditingText, True);
  end;
  //
  FEditingState := FALSE;
  if (Sender is TcxDBMemo) and
    ((TcxDBMemo(Sender).Text <> FMemoValue)) or FEditWasModified then begin
    TryPostMtValues;
    DoFieldChangeExit(TControl(Sender).Name);
  end;
  FEditWasModified := FALSE;
  ShowFieldState;
  ShowHintSb('');
end; {DoOnMemoExit}

procedure TfaMain.DoOnMemoEditing(Sender: TObject; var CanEdit: Boolean);
begin
  FEditWasModified := TRUE;
  if CanEdit then
    SetChangeFlag(TRUE);
end; {DoOnMemoEditing}

procedure TfaMain.DoNavig;
var
  dateString: string;
  calcValue: double;
begin
  if CEdit.FldType = fldtDate then begin //kalendar
    dateString := CEdit.Text;
    LogStat('k4');
    if CorrectDateString(dateString) then
      dateString := OpenCalendar(dateString,Left+5,Top+30)
    else
      dateString := OpenCalendar('',Left+5,Top+30);
    if dateString <> '' then begin
      CEdit.Text := dateString;
      CEdit.EditingText := dateString;
      MoveToNextControl(CEdit.NextDirection, CEdit.NextField);
    end
    else
      if CEdit.CanFocus then
        CEdit.SetFocus;
  end
  else if (CEdit.FldType = fldtNumber) or // kalkulacka
    (CEdit.FldType = fldtCurrency) then begin
    if mtFields.FindKey([UpperCase(CEdit.Hint)])
      {mtFields.Locate(mtFieldsName.FieldName, CEdit.Hint, //opt
      [loCaseInsensitive])}and mtFieldsHasList.Value then
      DoLists(CEdit.Hint)
    else begin
      calcValue := FCommonUtils.StrToFloatSafe(Replace(
        ThousandSeparator, CEdit.Text, ''));
{$IFDEF STANDALONE}
      LogStat('k3');
      if OpenCalcModal(calcValue, GetIniFileName,
        Left + 5, Top + 30) then begin
{$ELSE STANDALONE}
      LogStat('k3');
      if DoOpenCalcModal(calcValue,
        Left + 5, Top + 30) then begin
{$ENDIF STANDALONE}
        if ((CEdit.FldType = fldtNumber) or (CEdit.FldType = fldtCurrency)) and
          (CEdit.FldTypeDecimalPlaces = 0) then
          CEdit.Text := FloatToStr(RoundAri(calcValue, 0))
        else
          CEdit.Text := FloatToStr(calcValue);
        CEdit.EditingText := CEdit.Text;
        FEditWasModified := TRUE;
        MoveToNextControl(CEdit.NextDirection, CEdit.NextField);
      end;
    end;
  end
  else begin
    if mtFields.FindKey([UpperCase(CEdit.Hint)])
      {mtFields.Locate(mtFieldsName.FieldName, CEdit.Hint, //opt
      [loCaseInsensitive])}and mtFieldsHasList.Value then
      DoLists(CEdit.Hint)
    else begin
      LogStat('k5');
      DoOpenStrings;
    end;
  end;
end;

procedure TfaMain.DoOpenStrings;
{$IFNDEF STANDALONE}
var
  resStr: variant;
{$ENDIF STANDALONE}
begin
{$IFNDEF STANDALONE}
  if (FActuallyControl <> nil) and (FActuallyControl is TcxDBMemoEx) then begin
    resStr := OpenStrings(TcxDBMemoEx(FActuallyControl).Name,
      TcxDBMemoEx(FActuallyControl).Text,'',Left+5,Top+30);
    if resStr <> null then begin
      TcxDBMemoEx(FActuallyControl).Text := resStr;
      TcxDBMemoEx(FActuallyControl).EditingText := resStr;
    end;
  end
  else if CEdit.FldType = fldtString then begin
    resStr := OpenStrings(CEdit.Hint, CEdit.Text, '', Left+5, Top+30);
    if resStr <> null then begin
      CEdit.Text := resStr;
      CEdit.EditingText := resStr;
    end;
  end;
{$ENDIF STANDALONE}
end;

procedure TfaMain.DoNavigFromControl(AControl: TWinControl);
begin
  if AControl <> nil then
    DoLists(AControl.Name);
end;

//Posun tabelatorem z edicnich prvku

procedure TfaMain.SetNextTabControl(const AFieldName: string; ABack: boolean);
var
  c: TControl;
begin
  if ABack then begin
    c := FActuallyControl;
    MoveActuallyControl(VK_LEFT);
    if c = FActuallyControl then begin
      if cxTvContent.Visible and cxTvContent.CanFocus then
        cxTvContent.SetFocus
      else if cxContent.Visible and cxContent.CanFocus then
        cxContent.SetFocus
      else if (paComment.Height > Panel1.Height + 5) and
        reComment.Visible and reComment.CanFocus then
        reComment.SetFocus
    end
    else
  end
  else begin
    c := FActuallyControl;
    MoveActuallyControl(VK_RIGHT);
    if c = FActuallyControl then begin
      if (paComment.Height > Panel1.Height + 5) and
        reComment.Visible and reComment.CanFocus then
        reComment.SetFocus
      else if cxTvContent.Visible and cxTvContent.CanFocus then
        cxTvContent.SetFocus
      else if cxContent.Visible and cxContent.CanFocus then
        cxContent.SetFocus
    end;
  end;
end;

//Posun tabelatorem z ostatnich controls

procedure TfaMain.FocusNextTabControl(AControl: TWinControl; ABack: boolean);
begin
  if AControl = reInfo then begin
    if cxTvContent.Visible and cxTvContent.CanFocus then
      cxTvContent.SetFocus
    else if cxContent.Visible and cxContent.CanFocus then
      cxContent.SetFocus
    else if sbNotes.Visible then begin
      if reNotes.Visible and reNotes.CanFocus then
        reNotes.SetFocus;
    end
    else
      FocusFirstControl;
  end
  else if ABack then begin
    if (AControl = cxTvContent) or (AControl = cxContent) then begin
      if (paComment.Height > Panel1.Height + 5) and
        reComment.Visible and reComment.CanFocus then
        reComment.SetFocus
      else begin
        if sbNotes.Visible then begin
          if reNotes.Visible and reNotes.CanFocus then
            reNotes.SetFocus;
        end
        else
          FocusFirstControl;
      end;
    end
    else if AControl = reComment then begin
      if sbNotes.Visible then begin
        if reNotes.Visible and reNotes.CanFocus then
          reNotes.SetFocus;
      end
      else
        FocusFirstControl;
    end
    else if AControl = reNotes then begin
      if cxTvContent.Visible and cxTvContent.CanFocus then
        cxTvContent.SetFocus
      else if cxContent.Visible and cxContent.CanFocus then
        cxContent.SetFocus
      else
        if (paComment.Height > Panel1.Height + 5) and
          reComment.Visible and reComment.CanFocus then
          reComment.SetFocus;
    end;
  end
  else begin
    if AControl = reNotes then begin
      if (paComment.Height > Panel1.Height + 5) and
        reComment.Visible and reComment.CanFocus then
        reComment.SetFocus
      else begin
        if cxTvContent.Visible and cxTvContent.CanFocus then
          cxTvContent.SetFocus
        else if cxContent.Visible and cxContent.CanFocus then
          cxContent.SetFocus;
      end;
    end
    else if (AControl = cxTvContent) or (AControl = cxContent) then begin
      if sbNotes.Visible then begin
        if reNotes.Visible and reNotes.CanFocus then
          reNotes.SetFocus;
      end
      else
        FocusFirstControl;
    end
    else if AControl = reComment then begin
      if cxTvContent.Visible and cxTvContent.CanFocus then
        cxTvContent.SetFocus
      else if cxContent.Visible and cxContent.CanFocus then
        cxContent.SetFocus
      else begin
        if sbNotes.Visible then begin
          if reNotes.Visible and reNotes.CanFocus then
            reNotes.SetFocus;
        end
        else
          FocusFirstControl;
      end;
    end;
  end;
end;

//obsluha udalosti
procedure TfaMain.ApplicationEventsMessage(var Msg: tagMSG;
  var Handled: Boolean);
var a,b: integer;
  valString: string;
  cMem: TCxDBMemoEx;

  function TestValue: boolean;
  begin
    Result:=FALSE;
    if FEditingState and (CEdit.FldType = fldtDate) then begin
      valString := CEdit.Text;
      if CorrectDateString(valString) then begin
        CEdit.Text := valString;
        CEdit.EditingText := valString;
        Result:=TRUE;
      end;
    end
    else if FEditingState and
      ((CEdit.FldType = fldtNumber) or
      (CEdit.FldType = fldtCurrency)) then begin
      valString := CEdit.Text;
      if CorrectNumberString(valString,
        CEdit.FldTypeDecimalPlaces=0) then begin
        CEdit.Text := valString;
        CEdit.EditingText := valString;
        Result:=TRUE;
      end;
    end
    else begin
      Result:=TRUE;
    end;
  end;

begin
{$IFNDEF FINALBUILD}
  if (tmsDesigner <> nil) then begin
    //
  end
  else
{$ENDIF FINALBUILD}
  if Active and ((fmChecking = nil) or (not fmChecking.Focused)) and (fmPrintDialog = nil) and
    (fmCalendar = nil) then
  begin //kdyz jsou zobrazeny jine modalni formultare tak Active u obou
    //MYS
    //klepnuti mysi ukoncuje help k udaji a ulozi mtValues
    if ((Msg.message = WM_LBUTTONDOWN) or (Msg.message = WM_RBUTTONDOWN)) and
      FIsActiveFieldInstruction then begin
      MakeInactiveFieldInstructionPanel;
    end
    //ListBox
    else if (Msg.message = WM_LBUTTONDBLCLK) and //otevre vlozeny formular
      (ActiveControl <> nil) and
      (ActiveControl.Parent is TcxListBoxEx) then begin
      NestedButtonClick(TcxListBoxEx(ActiveControl.Parent).Name+'Edit');
      Handled := TRUE;
    end;
    //Osetreni skoku na udaj
    if Msg.message = WM_USERGotoField then begin
      GotoField(FGotoFieldName);
    end
    //zavreni okna - pro prepare report v nested forms
    else if Msg.message = WM_USERCloseForm then begin
      Close;
    end;
    //Kolecko mysi
    if (Msg.message = WM_MOUSEWHEEL) and (GetKeyState(VK_CONTROL) < 0) then begin
      if Msg.WParam>0 then begin
        ZoomUp;
        Handled := TRUE;
      end
      else if Msg.WParam<0 then begin
        ZoomDown;
        Handled := TRUE;
      end
    end;
    //KLAVESY
    //Alt+ ...
    if Msg.message = WM_SYSKEYDOWN then begin
      if not dxBarButtonDesignMode.Down then begin
        //EDIT
        if (CEdit <> nil) and CEdit.Focused then begin
          case Msg.wParam of
            //Alt+Down
            VK_DOWN: begin
                DoNavig;
                Handled := TRUE;
              end;
          end;
        end
        else if (ActiveControl <> nil) and
          (ActiveControl.Parent is TCxDBMemoEx) then begin
          case Msg.wParam of
            //Alt+Down
            VK_DOWN: begin
                DoNavigFromControl(ActiveControl.Parent);
                Handled := TRUE;
              end;
          end;
        end;
      end;
    end; {WM_SYSKEYDOWN}
    //Ostatni klavesy
    if Msg.message = WM_KEYDOWN then begin
      //HELP - stisk lib. klavesy ukoncuje help k udaji
      if (Msg.wParam <> VK_F1) and FIsActiveFieldInstruction then begin
        MakeInactiveFieldInstructionPanel;
        //kdyz uzivatel stiskne Esc tak to nemuzeme pustit dal protoze by si
        //zrusil doposud zadanou hodnotu
        if Msg.wParam = VK_ESCAPE then begin
          Handled := TRUE;
          EXIT;
        end;
      end;
      //FORMULAR
      //UZIVATELSKY MOD
      if not dxBarButtonDesignMode.Down then begin
        //EDIT
        if (CEdit <> nil) and CEdit.Focused then begin
          FEditWasModified := CEdit.EditModified or FEditWasModified;
            //v onDefault se nastavuje FEditWasModified
          case Msg.wParam of
            //Tabelator
            VK_Tab: begin
                SetNextTabControl(CEdit.Hint, GetKeyState(VK_SHIFT) < 0);
                Handled := TRUE;
              end;
            //Enter
            VK_RETURN: begin
              if TestValue then
                MoveToNextControl(CEdit.NextDirection, CEdit.NextField);
              if FEditWasModified then begin
                TryPostMtValues;
                DisplayCheck; // enter na udaji
              end;
              Handled := TRUE;
              end;
            //Right, Left, Home, End
            VK_RIGHT, VK_LEFT, VK_HOME, VK_END: begin
                if FEditingState then
                  Handled := FALSE
                else begin
                  MoveActuallyControl(Msg.wParam);
                  Handled := TRUE;
                end;
              end;
            //Down
            VK_DOWN: begin
                if (GetKeyState(VK_CONTROL) >= 0) and
                  (GetKeyState(VK_SHIFT) >= 0) then begin
                  if TestValue then
                    MoveActuallyControl(Msg.wParam);
                  if FEditWasModified then begin
                    TryPostMtValues;
                    DisplayCheck; // sipku dolu na udaji
                  end;
                  Handled := TRUE;
                end;
              end;
            VK_UP: begin
                if GetKeyState(VK_SHIFT) >= 0 then begin
                  //Up
                  if GetKeyState(VK_CONTROL) >= 0 then begin
                    if TestValue then
                      MoveActuallyControl(Msg.wParam);
                    if FEditWasModified then begin
                      TryPostMtValues;
                      DisplayCheck; // sipku nahoru na udaji
                    end;
                    Handled := TRUE;
                  end
                  //Ctrl+Up - otevreni seznamu
                  else begin
                    DoNavig;
                    Handled := TRUE;
                  end;
                end
                else begin
                  if GetKeyState(VK_CONTROL) < 0 then begin
                    {$IFNDEF STANDALONE}
                    SelectTextFromClientParams;
                    {$ENDIF STANDALONE}
                    Handled:=TRUE;
                  end
                  else
                    DoOpenStrings;
                end;
              end;
            //Insert
            VK_INSERT, VK_F2: begin
                ScrollToActuallyControl;
                SetEditState(TRUE);
                if (CEdit.FldType = fldtNumber) or
                  (CEdit.FldType = fldtCurrency) then
                  CEdit.EditingText := Replace(ThousandSeparator,
                    CEdit.EditingText, '');//bylo zakazano nevim proc, tak jsem povolil 21.12.2006
                Handled := TRUE;
              end;
            //Esc
            VK_ESCAPE: begin
{$IFDEF STANDALONE}
                SetEditState(FALSE);
                Handled := FALSE;
{$ELSE STANDALONE}
                if FEditingState then begin
                  SetEditState(FALSE);
                  Handled := FALSE;
                end
                else begin
                  Close;
                  Handled := TRUE;
                end;
{$ENDIF STANDALONE}
              end;
            //PgDn
            VK_NEXT: begin
                if GetKeyState(VK_CONTROL) >= 0 then begin
                  if TestValue then
                    ShowNextPage;
                  if FEditWasModified then begin
                    TryPostMtValues;
                    DisplayCheck; // na pgdn
                  end;
                  Handled := TRUE;
                end;
              end;
            //PgUp
            VK_PRIOR: begin
                if GetKeyState(VK_CONTROL) >= 0 then begin
                  if TestValue then
                    ShowPriorPage;
                  if FEditWasModified then begin
                    TryPostMtValues;
                    DisplayCheck; // na pgup
                  end;
                  Handled := TRUE;
                end;
              end;
            //Space - zakladni hodnota
            VK_SPACE: begin
                if (CEdit.Text = '') or (CEdit.SelText = CEdit.Text) then
                begin
                  DoDefault(CEdit.Hint);
                  Handled := TRUE;
                end;
              end;
            //Shift+F4 - zakladni hodnota
            VK_F4: begin
                a := GetKeyState(VK_SHIFT) and not GetKeyState(VK_CONTROL);
                if a < 0 then begin
                  DoDefault(CEdit.Hint);
                  Handled := TRUE;
                end;
              end;
            //F12, Shift+F12, Ctrl+Shift+F12
            VK_F12: begin
                a := GetKeyState(VK_SHIFT);
                b := GetKeyState(VK_CONTROL);
                if (a<0) and (b<0) then
                {$IFNDEF STANDALONE}
                  SelectTextFromClientParams
                {$ENDIF STANDALONE}
                else if (a<0)and(GListPressedChar='') then // druha podminka aby se otevrel seznam kdyz ma udaj masku vykriznik
                  DoOpenStrings
                else
                  DoNavig;
                Handled := TRUE;
              end;
          else
            {ScrollToActuallyControl;} //to je divne, proc na lib klavesu scrolovat
            BlinkLockFlag;
          end;
        end
        //CHECKBOX
        else if (ActiveControl <> nil) and
          (ActiveControl is TCxDBCheckBoxEx) then
        begin
          case Msg.wParam of
            //Tabelator
            VK_Tab: begin
                SetNextTabControl(TCxDBCheckBoxEx(ActiveControl).Name,
                  GetKeyState(VK_SHIFT) < 0);
                Handled := TRUE;
              end;
            //Enter
            VK_RETURN: begin
                MoveToNextControl(TCxDBCheckBoxEx(ActiveControl).NextDirection,
                  TCxDBCheckBoxEx(ActiveControl).NextField);
                Handled := TRUE;
              end;
            //Left, Right, Down, Up, Home, End
            VK_RIGHT, VK_LEFT, VK_DOWN, VK_UP, VK_HOME, VK_END: begin
                MoveActuallyControl(Msg.wParam);
                Handled := TRUE;
              end;
{$IFNDEF STANDALONE}
            //Esc
            VK_ESCAPE: begin
                Close;
                Handled := TRUE;
              end;
{$ENDIF STANDALONE}
            //PgDn
            VK_NEXT: begin
                ShowNextPage;
                Handled := TRUE;
              end;
            //PgUp
            VK_PRIOR: begin
                ShowPriorPage;
                Handled := TRUE;
              end;
            //Shift+F4 - zakladni hodnota
            VK_F4: begin
                a := GetKeyState(VK_SHIFT);
                if a < 0 then begin
                  DoDefault(TCxDBCheckBoxEx(ActiveControl).Name);
                  Handled := TRUE;
                end;
              end;
          else
            {ScrollToActuallyControl;} //to je divne, proc na lib klavesu scrolovat
            BlinkLockFlag;
          end;
          {TryPostMtValues;}
        end
        //ListBox
        else if (ActiveControl <> nil) and
          (ActiveControl.Parent is TcxListBoxEx) then begin
          case Msg.wParam of
            //Left, Right
            VK_RIGHT, VK_LEFT: begin
                MoveActuallyControl(Msg.wParam);
                Handled := TRUE;
              end;
            //Down, Up, Home, End
            VK_DOWN, VK_UP, VK_HOME, VK_END: begin
                if (GetKeyState(VK_SHIFT) >= 0) and
                  (GetKeyState(VK_CONTROL) >= 0) then begin
                  if TcxListBoxEx(ActiveControl.Parent).Count=0 then begin
                    MoveActuallyControl(Msg.wParam);
                    Handled := TRUE;
                  end;
                end;
              end;
            //F12
            VK_F12: begin
                if (TcxListBoxEx(ActiveControl.Parent).Count>0) and
                  (MessageAsk(Caption,sMsgAskOpenNestedForm,
                  [MBYES, MBNO]) = IDYES) then
                  NestedButtonClick(TcxListBoxEx(ActiveControl.Parent).Name+
                  'Edit');
                Handled := TRUE;
              end;
            //Tabelator
            VK_Tab: begin
                SetNextTabControl(TcxListBoxEx(ActiveControl.Parent).Name,
                  GetKeyState(VK_SHIFT) < 0);
                Handled := TRUE;
              end;
            //Ctrl+Enter
            VK_Return: begin
                SetNextTabControl(TcxListBoxEx(ActiveControl.Parent).Name,
                FALSE);
                Handled := TRUE;
              end;
            //Ctrl+Insert
            VK_INSERT: begin
                if GetKeyState(VK_CONTROL) < 0 then begin
                  if MessageAsk(Caption,sMsgAskInsertNestedForm,
                    [MBYES, MBNO]) = IDYES then
                    NestedButtonClick(TcxListBoxEx(ActiveControl.Parent).Name+
                    'Insert');
                  Handled := TRUE;
                end;
              end;
            //Ctrl+Delete
            VK_Delete: begin
                if GetKeyState(VK_CONTROL) < 0 then begin
                  if TcxListBoxEx(ActiveControl.Parent).Count>0 then
                    NestedButtonClick(TcxListBoxEx(ActiveControl.Parent).Name+
                    'Delete');
                  Handled := TRUE;
                end;
              end;
{$IFNDEF STANDALONE}
            //Esc
            VK_ESCAPE: begin
                Close;
                Handled := TRUE;
              end;
{$ENDIF STANDALONE}
            VK_NEXT: begin
                ShowNextPage;
                Handled := TRUE;
              end;
            VK_PRIOR: begin
                ShowPriorPage;
                Handled := TRUE;
              end;
          else
            {ScrollToActuallyControl;} //to je divne, proc na lib klavesu scrolovat
            BlinkLockFlag;
          end;
        end
        //Memo
        else if (ActiveControl <> nil) and
          (ActiveControl.Parent is TCxDBMemoEx) then begin
          case Msg.wParam of
            //Left, Right, Down, Up, Home, End
            VK_RIGHT, VK_LEFT, VK_DOWN, VK_UP, VK_HOME, VK_END: begin
                //Ctrl+Up
                if (Msg.wParam = VK_UP) and (GetKeyState(VK_SHIFT) >= 0) and
                  (GetKeyState(VK_CONTROL) < 0) then begin
                  if
                    mtFields.FindKey([UpperCase(TCxDBMemoEx(ActiveControl.Parent).Name)])
                  {mtFields.Locate(mtFieldsName.FieldName, //opt
                  TCxDBMemoEx(ActiveControl).Name,
                  [loCaseInsensitive])}and mtFieldsHasList.Value then begin
                    DoLists(TCxDBMemoEx(ActiveControl.Parent).Name);
                  end
                  else
                    DoOpenStrings;
                  Handled := TRUE;
                end
                //Shift+Up
                else if (Msg.wParam = VK_UP) and (GetKeyState(VK_SHIFT) < 0) and
                  (GetKeyState(VK_CONTROL) >= 0) then begin
                  DoOpenStrings;
                  Handled := TRUE;
                end
                else if (GetKeyState(VK_SHIFT) >= 0) and
                  (GetKeyState(VK_CONTROL) >= 0) then begin
                  cMem := TCxDBMemoEx(ActiveControl.Parent);
                  if (cMem.Text = '') or (cMem.SelText = cMem.Text) then begin
                    MoveActuallyControl(Msg.wParam);
                    Handled := TRUE;
                  end;
                end;
              end;
            //Insert
            VK_INSERT, VK_F2: begin
                ScrollToActuallyControl;
                SetEditState(TRUE);
                Handled := TRUE;
              end;
            //F4
            VK_F4: begin
                a := GetKeyState(VK_SHIFT) and not GetKeyState(VK_CONTROL);
                if a < 0 then begin //tento kod se ale nevykonava protoze to jde na Shift+F4 z menu z akci (faDefValueExecute)
                  DoDefault(TCxDBMemoEx(ActiveControl.Parent).Name);
                  Handled := TRUE;
                end
                else begin
                  cMem := TCxDBMemoEx(ActiveControl.Parent);
                  if FEditingState or
                    (cMem.SelText <> cMem.Text) then begin
                    ChangeMemoDiakr(TCxDBMemoEx(ActiveControl.Parent));
                    Handled := TRUE;
                  end;
                end;
              end;
            //Ctrl+Enter
            VK_Return: begin
                if GetKeyState(VK_CONTROL) < 0 then begin
                  MoveToNextControl(TCxDBMemoEx(ActiveControl.Parent).NextDirection,
                    TCxDBMemoEx(ActiveControl.Parent).NextField);
                  Handled := TRUE;
                end;
              end;
            //Tabelator
            VK_Tab: begin
                if ActiveControl.Parent is TCxDBMemoEx then begin
                  SetNextTabControl(TCxDBMemoEx(ActiveControl.Parent).Name,
                    GetKeyState(VK_SHIFT) < 0);
                  Handled := TRUE;
                end
                else begin
                  FocusNextTabControl(ActiveControl,
                    GetKeyState(VK_SHIFT) < 0);
                  Handled := TRUE;
                end;
              end;
{$IFNDEF STANDALONE}
            //Esc
            VK_ESCAPE: begin
                Close;
                Handled := TRUE;
              end;
{$ENDIF STANDALONE}
            VK_NEXT: begin
                ShowNextPage;
                Handled := TRUE;
              end;
            VK_PRIOR: begin
                ShowPriorPage;
                Handled := TRUE;
              end;
            //F12, Shift+F12
            VK_F12: begin
                a := GetKeyState(VK_SHIFT);
                b := GetKeyState(VK_CONTROL);
                if (a<0) and (b<0) then
                {$IFNDEF STANDALONE}
                  SelectTextFromClientParams
                {$ENDIF STANDALONE}
                else if a < 0 then
                  DoOpenStrings
                else begin
                  if
                    mtFields.FindKey([UpperCase(TCxDBMemoEx(ActiveControl.Parent).Name)])
                    {mtFields.Locate(mtFieldsName.FieldName, //opt
                    TCxDBMemoEx(ActiveControl).Name,
                    [loCaseInsensitive])}and mtFieldsHasList.Value then
                    DoLists(TCxDBMemoEx(ActiveControl.Parent).Name)
                  else
                    DoOpenStrings;
                end;
                Handled := TRUE;
              end;
          else
            {ScrollToActuallyControl;} //to je divne, proc na lib klavesu scrolovat
            BlinkLockFlag;
          end;
        end
        //Prilohy
        else if (ActiveControl <> nil) and
          (ActiveControl is TDBRichViewEdit) then begin
          case Msg.wParam of
            //Tabelator
            VK_Tab: begin
                if ActiveControl.Parent is TCxDBMemoEx then begin
                  if (GetKeyState(VK_SHIFT) < 0)or
                    (GetKeyState(VK_CONTROL) < 0) then begin
                      SetNextTabControl(TCxDBMemoEx(ActiveControl).Name,
                        GetKeyState(VK_SHIFT) < 0);
                    Handled := TRUE;
                  end;
                end
                else begin
                  if (GetKeyState(VK_SHIFT) < 0)or
                    (GetKeyState(VK_CONTROL) < 0) then begin
                    FocusNextTabControl(ActiveControl,
                      GetKeyState(VK_SHIFT) < 0);
                    Handled := TRUE;
                  end;
                end;
              end;
{$IFNDEF STANDALONE}
            //Esc
            VK_ESCAPE: begin
                if (ActiveControl = reComment) then
                  FocusActuallyControl
                else
                  Close;
                Handled := TRUE;
              end;
{$ELSE STANDALONE}
            //Esc
            VK_ESCAPE: begin //MiPi - Esc v STANDALONE zpusoboval smazani textu v RichView
                if (ActiveControl = reComment) then
                  FocusActuallyControl;
                Handled := TRUE;
              end;
{$ENDIF STANDALONE}
            VK_NEXT: begin
                ShowNextPage;
                Handled := TRUE;
              end;
            VK_PRIOR: begin
                ShowPriorPage;
                Handled := TRUE;
              end;
            //F12
            VK_F12: begin
                //DoNavigFromControl(ActiveControl.Parent);
                OpenStringsFromAppendix;
                Handled := TRUE;
              end;
            //Ctrl+Up
            VK_UP: begin
                a := GetKeyState(VK_SHIFT);
                b := GetKeyState(VK_CONTROL);
                if (a<0) and (b<0) then begin
                {$IFNDEF STANDALONE}
                  OpenClientParamFromAppendix;
                  Handled := TRUE;
                {$ENDIF STANDALONE}
                end
                else if (a < 0) or (b < 0) then begin
                  OpenStringsFromAppendix;
                  Handled := TRUE;
                end;
              end;
            //Insert (i Ctrl+Insert)
            VK_INSERT: begin
                if (GetKeyState(VK_SHIFT) >= 0) {and
                  (GetKeyState(VK_CONTROL) < 0)} then begin
                  DeleteRichViewDots;
                  Handled := TRUE;
                end;
              end;
          else
            BlinkLockFlag;
          end;
        end
        //obsah
        else if (ActiveControl <> nil) and
          ((ActiveControl.Parent = cxContent) or
          (ActiveControl = cxTvContent)) then begin
          case Msg.wParam of
            //Tabelator
            VK_Tab: begin
                FocusNextTabControl(ActiveControl, GetKeyState(VK_SHIFT) < 0);
                Handled := TRUE;
              end;
            VK_RETURN: begin
                if (cxTvContent.FocusedNode <> nil) and
                  not TryFocusControlByName(cxTvContent.FocusedNode.Values[6])
                  then
                  FocusFirstControl;
                Handled := TRUE;
              end;
{$IFNDEF STANDALONE}
            //Esc
            VK_ESCAPE: begin
                Close;
                Handled := TRUE;
              end;
{$ENDIF STANDALONE}
            //PgDn
            VK_NEXT: begin
                ShowNextPage;
                Handled := TRUE;
              end;
            //PgUp
            VK_PRIOR: begin
                ShowPriorPage;
                Handled := TRUE;
              end;
          end;
        end
        //Poznamka nebo poznamky
        else if (ActiveControl <> nil) and
          ((ActiveControl = reComment) or
          (ActiveControl = reNotes)) then begin
          case Msg.wParam of
{$IFNDEF STANDALONE}
            //Esc
            VK_ESCAPE: begin
                Close;
                Handled := TRUE;
              end;
{$ENDIF STANDALONE}
            //Tabelator
            VK_Tab: begin
                FocusNextTabControl(ActiveControl, GetKeyState(VK_SHIFT) < 0);
                Handled := TRUE;
              end;
          end;
        end
        //Informace
        else if (ActiveControl <> nil) and (ActiveControl = reInfo) then begin
          case Msg.wParam of
            //Tabelator
            VK_Tab, VK_RETURN, VK_ESCAPE: begin
                FocusNextTabControl(ActiveControl, FALSE);
                Handled := TRUE;
              end;
          end;
        end
        else begin
          case Msg.wParam of
            //Tabelator
            VK_F12: begin
                Handled := TRUE;
              end;
          end;
        end;
        case Msg.wParam of
          //Ctrl+ Num+
          VK_ADD: begin
              b := GetKeyState(VK_CONTROL);
              if (b<0) then begin
                ZoomUp;
                Handled := TRUE;
              end;
            end;
          //Ctrl+ Num-
          VK_SUBTRACT: begin
              b := GetKeyState(VK_CONTROL);
              if (b<0) then begin
                ZoomDown;
                Handled := TRUE;
              end;
            end;
          //Ctrl+ Num0
          VK_NUMPAD0: begin
              b := GetKeyState(VK_CONTROL);
              if (b<0) then begin
                ZoomNormal;
                Handled := TRUE;
              end;
            end;
        end;
      end
      //NAVRHOVY MOD -----------------------------------------------------------
      else begin
        if (ActiveControl <> nil) and
          ((ActiveControl.Parent = cxContent)or
          (ActiveControl.Parent.Parent.Parent = cxContent)) then begin // kdyz jsme uvnitr bunky
          case Msg.wParam of
            //Tabelator
            VK_Tab: begin
                FocusFirstControl;
                Handled := TRUE;
              end;
            VK_F2: begin // vstup do udaje v mrizce na F2
                if dxBarButtonDesignMode.Down and
                  (ActiveControl.Parent = cxContent) then
                  ActiveControl.Perform(WM_KEYDOWN, VK_RETURN, 0);
              end;
          end;
        end
        //EDIT
        else if (CEdit <> nil) and CEdit.Focused then begin
          case Msg.wParam of
            //Tabelator
            VK_Tab: begin
                SetNextTabControl(CEdit.Hint, GetKeyState(VK_SHIFT) < 0);
                Handled := TRUE;
              end;
            //Enter
            VK_RETURN: begin
              MoveToNextControl(CEdit.NextDirection, CEdit.NextField);
              Handled := TRUE;
              end;
            //Right, Left, Home, End
            VK_RIGHT, VK_LEFT, VK_HOME, VK_END: begin
                MoveActuallyControl(Msg.wParam);
                Handled := TRUE;
              end;
            //Down
            VK_DOWN: begin
                if (GetKeyState(VK_CONTROL) >= 0) and
                  (GetKeyState(VK_SHIFT) >= 0) then begin
                  MoveActuallyControl(Msg.wParam);
                  Handled := TRUE;
                end;
              end;
            VK_UP: begin
                if (GetKeyState(VK_CONTROL) >= 0) and
                  (GetKeyState(VK_SHIFT) >= 0) then begin
                  MoveActuallyControl(Msg.wParam);
                  Handled := TRUE;
                end;
              end;
            //PgDn
            VK_NEXT: begin
                if GetKeyState(VK_CONTROL) >= 0 then begin
                  ShowNextPage;
                  Handled := TRUE;
                end;
              end;
            //PgUp
            VK_PRIOR: begin
                if GetKeyState(VK_CONTROL) >= 0 then begin
                  ShowPriorPage;
                  Handled := TRUE;
                end;
              end;
          else
            ScrollToActuallyControl;
            BlinkLockFlag;
          end;
        end
        //CHECKBOX
        else if (ActiveControl <> nil) and
          (ActiveControl is TCxDBCheckBoxEx) then
        begin
          case Msg.wParam of
            //Tabelator
            VK_Tab: begin
                SetNextTabControl(TCxDBCheckBoxEx(ActiveControl).Name,
                  GetKeyState(VK_SHIFT) < 0);
                Handled := TRUE;
              end;
            //Enter
            VK_RETURN: begin
                MoveToNextControl(TCxDBCheckBoxEx(ActiveControl).NextDirection,
                  TCxDBCheckBoxEx(ActiveControl).NextField);
                Handled := TRUE;
              end;
            //Left, Right, Down, Up, Home, End
            VK_RIGHT, VK_LEFT, VK_DOWN, VK_UP, VK_HOME, VK_END: begin
                MoveActuallyControl(Msg.wParam);
                Handled := TRUE;
              end;
            //PgDn
            VK_NEXT: begin
                ShowNextPage;
                Handled := TRUE;
              end;
            //PgUp
            VK_PRIOR: begin
                ShowPriorPage;
                Handled := TRUE;
              end;
          else
            ScrollToActuallyControl;
            BlinkLockFlag;
          end;
        end
        else if (ActiveControl <> nil) and
          (ActiveControl.Parent is TCxDBMemoEx) then begin
          case Msg.wParam of
            //Left, Right, Down, Up, Home, End
            VK_RIGHT, VK_LEFT, VK_DOWN, VK_UP, VK_HOME, VK_END: begin
                if (GetKeyState(VK_SHIFT) >= 0) and
                  (GetKeyState(VK_CONTROL) >= 0) then begin
                  cMem := TCxDBMemoEx(ActiveControl.Parent);
                  if (cMem.Text = '') or (cMem.SelText = cMem.Text) then begin
                    MoveActuallyControl(Msg.wParam);
                    Handled := TRUE;
                  end;
                end;
              end;
            //Ctrl+Enter
            VK_Return: begin
                if GetKeyState(VK_CONTROL) < 0 then begin
                  MoveToNextControl(TCxDBMemoEx(ActiveControl.Parent).NextDirection,
                    TCxDBMemoEx(ActiveControl.Parent).NextField);
                  Handled := TRUE;
                end;
              end;
            //Tabelator
            VK_Tab: begin
                if ActiveControl.Parent is TCxDBMemoEx then begin
                  SetNextTabControl(TCxDBMemoEx(ActiveControl.Parent).Name,
                    GetKeyState(VK_SHIFT) < 0);
                  Handled := TRUE;
                end
                else begin
                  FocusNextTabControl(ActiveControl,
                    GetKeyState(VK_SHIFT) < 0);
                  Handled := TRUE;
                end;
              end;
            VK_NEXT: begin
                ShowNextPage;
                Handled := TRUE;
              end;
            VK_PRIOR: begin
                ShowPriorPage;
                Handled := TRUE;
              end;
          else
            ScrollToActuallyControl;
            BlinkLockFlag;
          end;
        end;
      end;
    end;
  end;
end; {ApplicationEventsMessage}

