function TfaMain.TranslateFieldNames(const AScript: string): string;
//var
  //start: TDateTime;
const
  cLeftFldBracket = '[.';
  cRightFldBracket = '.]';
  cLeftFldBracketAsString = '[:';
  cRightFldBracketAsString = ':]';
  cLeftFldBracketNumber = '[*';
  cRightFldBracketNumber = '*]';
  cLeftFldBracketNumberStr = '[=';
  cRightFldBracketNumberStr = '=]';

  cLeftPartOfField = ' GetMTVField(''';
  cRightPartOfField = ''').Value ';
  cRightPartOfFieldAsString = ''').AsString ';

  cLeftPartOfFieldNumber = ' GetMTVFieldValue(''';
  cRightPartOfFieldNumber = ''',''*]'') ';
  cRightPartOfFieldNumberStr = ''',''=]'') ';

  //Marek: reseni, ktere se pouzivalo pro TMS scritper nez jsem zaradil tms_kbMTGetFieldValueProc
  //pred zarazenim totiz TField.Value vracel null
  //!!!POKUD SE SMAZE, MUZE SE SMAZAT I GetMTVFieldAsType!!!!
  {function DoTranslate: string;
  var
    i, y: integer;
    scr, scrNew: string;
    s, s1, oldFld, oldFldBrc: string;
  begin
    scr := AScript;
    scrNew := '';
    oldFld := '';
    oldFldBrc := '';
    //
    i := 1;
    while i <= Length(scr) do begin
      s := scr[i];
      s1 := scr[i+1];
      if (s = '[') and ((s1 = '.') or (s1 = ':') or (s1 = '*') or (s1 = '=')) then begin
        oldFld := '';
        oldFldBrc := s+s1;
        if (s1 = '.') or (s1 = ':') then //. :
          scrNew := scrNew + cLeftPartOfField
        else                             //* =
          scrNew := scrNew + cLeftPartOfFieldNumber;
        for y := i+2 to Length(scr) do begin
          if (scr[y] = s1) and (scr[y+1] = ']') then begin
            oldFldBrc := oldFldBrc+oldFld+s1+']';
            if (s1 = '.') then
              scrNew := scrNew + GetMTVFieldAsType(oldFld)
            else if (s1 = ':') then
              scrNew := scrNew + cRightPartOfFieldAsString
            else if (s1 = '*') then
              scrNew := scrNew + cRightPartOfFieldNumber
            else if (s1 = '=') then
              scrNew := scrNew + cRightPartOfFieldNumberStr;
            Break;
          end
          else begin
            oldFld := oldFld + scr[y];
            scrNew := scrNew + scr[y];
          end;
        end;
      end
      else
        scrNew := scrNew + scr[i];
      //
      if oldFldBrc <> '' then
        i := i + Length(oldFldBrc)
      else
        i := i + 1;
      //
      oldFld := '';
      oldFldBrc := '';
    end;
    Result := scrNew;    
  end;}

begin
  //start := now;
  {if FNewScripter then begin
    Result := DoTranslate;
  end
  else} begin
    Result := Replace(cLeftFldBracket, AScript, cLeftPartOfField);
    Result := Replace(cRightFldBracket, Result, cRightPartOfField);
    //
    Result := Replace(cLeftFldBracketAsString, Result, cLeftPartOfField);
    Result := Replace(cRightFldBracketAsString, Result, cRightPartOfFieldAsString);
    //
    Result := Replace(cLeftFldBracketNumber, Result, cLeftPartOfFieldNumber);
    Result := Replace(cRightFldBracketNumber, Result, cRightPartOfFieldNumber);
    //
    Result := Replace(cLeftFldBracketNumberStr, Result, cLeftPartOfFieldNumber);
    Result := Replace(cRightFldBracketNumberStr, Result, cRightPartOfFieldNumberStr);
  end;
  //showmessage(FormatDateTime('ss:zzz', now-start));
  //SaveStringToFile(Result,'d:\aa.txt');
end; {TranslateFieldNames}

function TfaMain.TranslateIniProcs(const AScript: string): string;
var
  sl: TStringList;
  i, pIni, pDelim: integer;

  function PosIni(const ARadek, AIniIdentificator: string): integer;
  begin
    Result := Pos(' '+AIniIdentificator+'(', AnsiUpperCase(sl[i]));
    if Result>0 then 
      Result:=Result+1
    else begin
      Result := Pos(AIniIdentificator+'(', AnsiUpperCase(sl[i]));
      if Result>1 then
        Result:=0;
    end;
  end;

begin
  sl := TStringList.Create;
  try
    sl.Text := AScript;
    for i := 0 to sl.Count - 1 do begin
      pIni := PosIni(sl[i],'INI');
      if pIni > 0 then begin
        pDelim := pIni;
        while (pDelim <= Length(sl[i])) and (Copy(sl[i], pDelim, 1) <> ',') do
          INC(pDelim);
        if Copy(sl[i], pDelim, 1) = ',' then begin
          sl[i] := Copy(sl[i], 1, pIni - 1) +
            'if (GScriptState = ssInit) or (GScriptState = ssDefault) and (UpperCase(GScriptFieldName)=UpperCase(' +
            Copy(sl[i], pIni + 4, pDelim - pIni - 4) +
            ')) then ' + Copy(sl[i], pIni, maxint);
        end;
      end;
      //Ino
      pIni := PosIni(sl[i],'INO');
      if pIni > 0 then begin
        pDelim := pIni;
        while (pDelim <= Length(sl[i])) and (Copy(sl[i], pDelim, 1) <> ',') do
          INC(pDelim);
        if Copy(sl[i], pDelim, 1) = ',' then begin
          sl[i] := Copy(sl[i], 1, pIni - 1) +
            'if GScriptState = ssInit then ' + Copy(sl[i], pIni, maxint);
        end;
      end;
      //Def
      pIni := PosIni(sl[i],'DEF');
      if pIni > 0 then begin
        pDelim := pIni;
        while (pDelim <= Length(sl[i])) and (Copy(sl[i], pDelim, 1) <> ',') do
          INC(pDelim);
        if Copy(sl[i], pDelim, 1) = ',' then begin
          sl[i] := Copy(sl[i], 1, pIni - 1) +
            'if (GScriptState = ssDefault) and (UpperCase(GScriptFieldName)=UpperCase(' +
            Copy(sl[i], pIni + 4, pDelim - pIni - 4) +
            ')) then ' + Copy(sl[i], pIni, maxint);
        end;
      end;
    end;
    Result := sl.Text;
  finally
    sl.Free;
  end;
end;


