    if not (mtTskp.State in [dsEdit, dsInsert]) then
      mtTskp.Edit;
    mtTskpCreateDate.Value := now;
    mtTskpModifiedDate.Value := now;
    mtTskpAutor.Value := GetWinUserName;
    mtTskp.Post;
    StartModifiedTime;
  end;
end;

