procedure TfaMain.SetGScriptFieldName;
begin
if FActuallyControl <> nil then begin
    if FActuallyControl = CEdit then
      FScriptFieldName := CEdit.Hint
    else
      FScriptFieldName := FActuallyControl.Name;
  end
  else
