//{$IFNDEF STANDALONE}
//  if not mtValues.ReadOnly then // zruseno 14.9.2017 Mik, proc by to mělo byt jen pro FS a ne pro FA - zpusobovalo to rozeditovani vnoreneho formulare pri jeho otevreni 
