function TfaMain.PrepareReportFile(const ADstFileName: string;
  AFromPage: Integer = 0): string;
var
  reportSettings: TReportSettings;
  s: string;
begin
  Result:='';
  if mtDef.Active then begin
    reportSettings := LoadReportSettings(GetIniFileName);
    reportSettings := ApplyRestrictReportOptions(reportSettings);
    reportSettings := ApplyAllPages(reportSettings);
    s:='';
    if reportSettings.VariantName<>sReportVariantBasic then
      s:=GetStringLineName(FReportVariantsTexts, reportSettings.VariantName);
    if s<>'' then
      s:='#'+s;

    if AFromPage>0 then
      SetFormUserSetting(cUSPrintFromPage, IntToStr(AFromPage));
    Result:=ExtractFileName(PreviewForm(NormalPath(ExtractFilePath(
      FDefFileName)) + mtDefID.Value + s + cReportDefaultExt,
      FALSE, FALSE, TRUE, reportSettings, ADstFileName));
    if AFromPage>0 then
      SetFormUserSetting(cUSPrintFromPage, IntToStr(1));
  end;
end;

