  if APosition<0 then begin //hide
    pbStatus.Position:=0;
    //
    paProgress.Align:=alNone;
    paProgress.Visible:=false;
    laZoomMinus.Visible:=true;
    laZoomPlus.Visible:=true;
    laZoomProc.Visible:=true;
    tbZoom.Visible:=true;
    //
    paZoom.Refresh;
  end
  else if APosition=0 then begin //init
    pbStatus.Properties.Max:=AMax;
    pbStatus.Position:=0;
    //
    paProgress.Align:=alLeft;
    paProgress.Visible:=true;
    laZoomMinus.Visible:=false;
    laZoomPlus.Visible:=false;
    laZoomProc.Visible:=false;
    tbZoom.Visible:=false;
    //
    paZoom.Refresh;
  end
