procedure TfaMain.FAToFront;
begin
  if WindowState = wsMinimized then
    WindowState := wsNormal;

  // Simulovat Alt (Windows pak povolí SetForegroundWindow)
  keybd_event(VK_MENU, 0, KEYEVENTF_EXTENDEDKEY or 0, 0);
  SetForegroundWindow(Application.Handle);
  keybd_event(VK_MENU, 0, KEYEVENTF_EXTENDEDKEY or KEYEVENTF_KEYUP, 0);

  Application.BringToFront;
  SetFocus;
end;

procedure TfaMain.AppDone;
begin
  TimerPoll.Enabled := False;
  FreeAndNil(FBridge);
end;

procedure TfaMain.TimerPollTimer(Sender: TObject);
begin
  //OutputDebugString('TimerPoll tick');
  if Assigned(FBridge) then
  begin
    FBridge.PollTick; // detekuje Ctrl+S v Cursoru a případně zavolá BridgeExternalSave
      // Aktualizuj stav debuggeru do Cursor (pokud není aktivní původní debugger)
    UpdateDebugState;
  end;
end;

procedure TfaMain.BridgeExternalSave(const Text: AnsiString);
var
  isChangingScript, btSaveEnabled: boolean;
begin
  if FCurrentFormId <> '' then
  begin
    FAToFront;
    btSaveEnabled:=dxBarButtonSave.Enabled;
    isChangingScript:=FIsChangingScript;
    FIsChangingScript:=TRUE; //aby se neprovadelo calculate
    try
      SaveCodeToDB(Text);

      SaveFormScript;
      ReloadListBoxes;
      BringToFront;
    finally
      dxBarButtonSave.Enabled := btSaveEnabled;
      FIsChangingScript:=isChangingScript;
    end;
  end;
end;

function TfaMain.LoadCodeFromDB: AnsiString;
begin
  Result := AnsiToUtf8(mtDefScript.Value);
end;

procedure TfaMain.SaveCodeToDB(const Code: AnsiString);
begin
  if mtDef.State = dsBrowse then
    mtDef.Edit;
  mtDefScript.Value := '';
  mtDefScript.Value := Utf8ToAnsi(Code);
  mtDef.Post;
  SaveFormScript;
end;

procedure TfaMain.ActionCtrlQExecute;
var
  Code: AnsiString;
  JumpLine, JumpCol: Integer;
begin
  JumpLine := 0;
  JumpCol := 0;
  // identifikace aktuálního formuláře v FA
  FCurrentFormId := mtDefID.Value; // vaše logika

  // načtení kódu z DB (aktuální stav v FA)
  Code := LoadCodeFromDB;

  // volitelně – pozice kurzoru z vašeho editoru (jinak dejte 0,0 a skok se neprovede)
  //GetEditorCaret(0,JumpLine, JumpCol); // vaše logika; když neřešíte, nastavte obě na 0
 //GetEditorCaret(0, 0); // vaše logika; když neřešíte, nastavte obě na 0

  if (FBridge.CurrentFile = '') or (FBridge.CurrentFormId <> FCurrentFormId) then
  begin
    // první otevření pro daný FormId
    if not FBridge.StartEditing(FCurrentFormId, Code, JumpLine, JumpCol) then
      ShowMessage('Nepodařilo se spustit Cursor / VS code. Patrně není otevřený formulář nebo je špatně cesta.');
  end
  else
  begin
    // opakované Ctrl+Q – přepíše soubor aktuálním stavem z FA a přepne do Cursoru
    if not FBridge.BringToCursor(Code, JumpLine, JumpCol) then
      ShowMessage('Nepodařilo se přepnout do Cursoru / VS code.');
  end;
end;

